<?php
require_once __DIR__.'/config/config.php';
$province=trim($_GET['province']??'');$district=trim($_GET['district']??'');$service=trim($_GET['service']??'');
$where='WHERE active=1';$params=[];
if($province!==''){$where.=' AND (province=? OR province IS NULL)';$params[]=$province;}
if($district!==''){$where.=' AND (district=? OR district IS NULL)';$params[]=$district;}
if($service!==''){$where.=' AND service=?';$params[]=$service;}
$st=db()->prepare("SELECT * FROM emergency_contacts $where ORDER BY CASE WHEN province IS NULL THEN 0 ELSE 1 END,service,organization");$st->execute($params);$contacts=$st->fetchAll();
$quick=db()->query("SELECT * FROM emergency_contacts WHERE active=1 AND province IS NULL AND district IS NULL AND service IN ('Police','Fire','Ambulance','Disaster','APF') ORDER BY FIELD(service,'Police','Ambulance','Fire','Disaster','APF')")->fetchAll();
$locationData=nepal_locations();$services=db()->query('SELECT DISTINCT service FROM emergency_contacts WHERE active=1 ORDER BY service')->fetchAll(PDO::FETCH_COLUMN);
function emergency_phone_link(string $phone): ?string { return preg_match('/^\+?[0-9][0-9 ()-]+$/',$phone)?'tel:'.preg_replace('/[^0-9+]/','',$phone):null; }
function verification_label(string $status): string { return ['OFFICIAL'=>'Officially verified','LOCAL_VERIFIED'=>'Verified by local authority','NEEDS_VERIFICATION'=>'Needs verification','REPORTED_INACTIVE'=>'Reported inactive'][$status]??$status; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Emergency Help Directory - Nepal Disaster Archive</title><style>:root{--ink:#17202a;--paper:#f7f3ed;--red:#9e2b25;--line:#d9d0c6;--muted:#5f6665}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,serif}.nav{position:sticky;top:0;background:#111820;color:#fff;z-index:3;padding:15px 5%;display:flex;align-items:center;gap:25px;font:13px Arial}.nav a{color:#fff;text-decoration:none}.logo{font-weight:900;letter-spacing:2px}.navlinks{margin-left:auto;display:flex;gap:18px}.hero{padding:72px 7% 55px;background:#5b2220;color:#fff}.wrap{width:min(1150px,90%);margin:auto}.eyebrow{font:800 12px Arial;text-transform:uppercase;letter-spacing:1px;color:#f0c2b8}.hero h1{font-size:clamp(44px,7vw,78px);line-height:.95;margin:15px 0 22px}.hero p{font-size:20px;line-height:1.6;color:#f2ded8;max-width:780px}.section{padding:55px 0}.quick{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:-35px;position:relative}.quick-card,.contact{background:#fff;border:1px solid var(--line);border-radius:8px;padding:20px}.quick-card{border-top:4px solid var(--red)}.quick-card h2{font-size:18px;margin:0 0 8px}.number,.phone{font:800 25px Arial;color:var(--red);word-break:break-word}.call{display:inline-block;margin-top:12px;color:#fff;background:var(--red);padding:9px 12px;border-radius:5px;text-decoration:none;font:700 13px Arial}.intro{font-size:19px;line-height:1.7;color:#555;max-width:820px}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:28px 0}.filters select,.filters button{padding:13px;border:1px solid var(--line);border-radius:6px;background:#fff;font:15px Arial}.filters button{background:var(--red);color:#fff;border-color:var(--red);font-weight:700}.directory{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.service{font:800 12px Arial;text-transform:uppercase;letter-spacing:1px;color:var(--red)}.contact h2{margin:8px 0;font-size:22px}.contact p{color:#555;line-height:1.55;margin:8px 0}.phone-link{color:var(--red);text-decoration:none}.badge{display:inline-block;padding:5px 8px;border-radius:999px;font:700 11px Arial;margin-top:12px}.official{background:#d9eedf;color:#17602c}.local_verified{background:#dceaf5;color:#1e5877}.needs_verification{background:#f7e4c2;color:#764d00}.reported_inactive{background:#f3d9d7;color:#8a211c}.verified{font:13px Arial;color:var(--muted);margin-top:10px}.note,.empty{padding:18px;background:#eee9e2;font:14px/1.6 Arial;color:#555}.note{margin-top:35px;border-left:4px solid var(--red)}@media(max-width:900px){.quick{grid-template-columns:repeat(2,1fr)}.directory{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.navlinks{display:none}.quick,.directory{grid-template-columns:1fr}}</style></head><body><?php require_once __DIR__ . '/includes/public-nav.php'; ?><header class="hero"><div class="wrap"><div class="eyebrow">Emergency help - Nepal</div><h1>Emergency Help Directory</h1><p>If you are in immediate danger, call the relevant emergency service first. Fire and ambulance dispatch arrangements vary by locality, so use the local directory below when available.</p></div></header><main><section class="section"><div class="wrap"><div class="quick"><?php foreach($quick as $item):$link=emergency_phone_link($item['phone']);?><article class="quick-card"><h2><?=e($item['organization'])?></h2><div class="number"><?=e($item['phone'])?></div><p><?=e($item['availability_note']?:$item['title'])?></p><?php if($link):?><a class="call" href="<?=e($link)?>">Call <?=e($item['phone'])?></a><?php endif;?></article><?php endforeach;?></div></div></section><section class="section" style="padding-top:0"><div class="wrap"><h2>Find local help</h2><p class="intro">Choose a province, district, or service to find relevant contacts. National contacts remain visible when a local filter is selected.</p><form class="filters"><select name="province" id="province"><option value="">All provinces</option><?php foreach(array_keys($locationData) as $item):?><option value="<?=e($item)?>" <?=$province===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select><select name="district" id="district"><option value="">All districts</option><?php foreach($locationData as $provinceName=>$districts):foreach($districts as $item):?><option value="<?=e($item)?>" data-province="<?=e($provinceName)?>" <?=$district===$item?'selected':''?>><?=e($item)?></option><?php endforeach;endforeach;?></select><select name="service"><option value="">All services</option><?php foreach($services as $item):?><option value="<?=e($item)?>" <?=$service===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select><button>Find help</button></form><div class="directory"><?php foreach($contacts as $item):$link=emergency_phone_link($item['phone']);?><article class="contact"><div class="service"><?=e($item['service'])?></div><h2><?=e($item['organization'])?></h2><p><strong><?=e($item['title'])?></strong></p><div class="phone"><?php if($link):?><a class="phone-link" href="<?=e($link)?>"><?=e($item['phone'])?></a><?php else:?><?=e($item['phone'])?><?php endif;?></div><?php if($item['province']||$item['district']):?><p><?=e(trim(($item['district']?:'').' '.($item['province']?:'')))?></p><?php endif;?><?php if($item['address']):?><p><?=e($item['address'])?></p><?php endif;?><?php if($item['coverage']):?><p><strong>Coverage:</strong> <?=e($item['coverage'])?></p><?php endif;?><?php if($item['availability_note']):?><p><?=e($item['availability_note'])?></p><?php endif;?><span class="badge <?=strtolower(e($item['verification_status']))?>">✓ <?=e(verification_label($item['verification_status']))?></span><?php if($item['last_verified']):?><div class="verified">Last verified: <?=e(date('j F Y',strtotime($item['last_verified'])))?></div><?php endif;?></article><?php endforeach;?><?php if(!$contacts):?><div class="empty">No active contacts match these filters. Try a broader location or service.</div><?php endif;?></div><div class="note"><strong>Emergency directory safety note:</strong> Numbers and service availability can change. Last verified dates show when this archive checked a record; follow current instructions from the responsible authority. Do not use this page instead of emergency services in immediate danger.</div></div></section></main><script>var province=document.getElementById('province'),district=document.getElementById('district'),options=Array.from(district.options);province.addEventListener('change',function(){var value=province.value;district.innerHTML='';options.forEach(function(option,index){if(index===0||!value||option.dataset.province===value)district.appendChild(option.cloneNode(true))});district.value='';});</script></body></html>
